INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_DBENG_2021H1_YY', 'RK_DBENG_2021H1_YY_Q001', '试题一', 1, '案例分析', '[]', '{"questionType":"案例分析","sourceQuestionNo":1,"imageHashValues":["8a105f76a62aa6c9199d62619adf990881701b5012aee944d7b890161b6085dc","532da7d7aa9e20c3801b4805cd852d8eeab0bb095f7c81df03e486cc4592e702","969f4650e2107b3c182762788b2c6d6c0fed181e5791b45b3c574ce985e5581f","9e88a63261d82e72be862ef5160b6b453cfa4140c8897960fc6aa0ea8dbf2e30","59acd63d1f11c40957995da8fb7d67ace363cfe3d2120564507f3553fe89d54e","81c59ef53406c657dc5f75573cb844741aa2ac35c24b6f3e3bc986820c6aaf85","8e99e7be13c18ad0dee15f1f6f36ad2cd965b39069db0cd52af24d81cecc355a","93fc2f3d2960308931cc8e3fedc73adcf4e1aec9017bf83ae4e8b84953e73b38","28eb5ab2a95b7baead4fbd390d4e908bca002e2ba3af8252df06d98dd2a7becb","01f6c628d57b35868a1180ead3a410472d2aed1d613469a035852b783bb753ef","f10fe5dab9579ce2b40342049feb06fce1a1950b49134c0cf28cacc32947c67a","4a3810eccf399069b065ed5c09a0df749a1933983be22a84a8ffc9b1baf9f09c","f40a142fd51f8a3cea2eaae476dedd6b6b2781747f8a150fb9ad03ef4407d719","b2e0f5bf7329ac5c0c1acee991ac62df97bd2fbc88454ec85d96bac639b306b9","b22aeb854284e0da335e5f4b9ec70e662d36c788d465d01dcd19241be0ed32ee","8a913b18b9fff31ea69b57cfa36843646773e4d3b9935bf57ae1445ee2f1da58","3eb8ac7aaf1154898cb5005a9cc0bec344afe7e34e5e718c323c617ddc67856a"],"fullQuestionName":"试题一(共15分)\\n某社区蔬菜团购网站，为规范商品收发流程，便于查询客户订单情况，需要开发一个信息系统。请根据下述需求描述完成该系统的数据库设计。\\n[需求描述]\\n(1)记录蔬菜供应商的信息，包括供应商编号、地址和一个电话。\\n(2)记录社区团购点的信息，包括团购点编号、地址和一个电话。\\n(3)记录客户信息，包括客户姓名和一个电话。客户可以在不同的社区团购点下订单，不直接与蔬菜供应商发生联系。\\n(4)记录客户订单信息，包括订单编号、团购点编号、客户电话、订单内容和日期。\\n概念模型设计\\n根据需求阶段收集的信息，设计的实体联系图(不完整)如图1-1所示。\\n 【img:8a105f76a62aa6c9199d62619adf990881701b5012aee944d7b890161b6085dc】 【img:532da7d7aa9e20c3801b4805cd852d8eeab0bb095f7c81df03e486cc4592e702】 【img:969f4650e2107b3c182762788b2c6d6c0fed181e5791b45b3c574ce985e5581f】 【img:9e88a63261d82e72be862ef5160b6b453cfa4140c8897960fc6aa0ea8dbf2e30】 【img:59acd63d1f11c40957995da8fb7d67ace363cfe3d2120564507f3553fe89d54e】 【img:81c59ef53406c657dc5f75573cb844741aa2ac35c24b6f3e3bc986820c6aaf85】 【img:8e99e7be13c18ad0dee15f1f6f36ad2cd965b39069db0cd52af24d81cecc355a】 【img:93fc2f3d2960308931cc8e3fedc73adcf4e1aec9017bf83ae4e8b84953e73b38】 【img:28eb5ab2a95b7baead4fbd390d4e908bca002e2ba3af8252df06d98dd2a7becb】 【img:01f6c628d57b35868a1180ead3a410472d2aed1d613469a035852b783bb753ef】 【img:f10fe5dab9579ce2b40342049feb06fce1a1950b49134c0cf28cacc32947c67a】 2021年上半年数据库系统工程师下午答案及解析\\n 【img:4a3810eccf399069b065ed5c09a0df749a1933983be22a84a8ffc9b1baf9f09c】 【img:f40a142fd51f8a3cea2eaae476dedd6b6b2781747f8a150fb9ad03ef4407d719】 【img:b2e0f5bf7329ac5c0c1acee991ac62df97bd2fbc88454ec85d96bac639b306b9】 【img:b22aeb854284e0da335e5f4b9ec70e662d36c788d465d01dcd19241be0ed32ee】 【img:8a913b18b9fff31ea69b57cfa36843646773e4d3b9935bf57ae1445ee2f1da58】 【img:3eb8ac7aaf1154898cb5005a9cc0bec344afe7e34e5e718c323c617ddc67856a】","displayTitle":"试题一"}')
